import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080";tok=None
def newtok():
    global tok
    r=urllib.request.Request(B+"/token",method="POST");tok=json.load(urllib.request.urlopen(r))["token"]
def get(p):
    global tok
    for i in range(200):
        if not tok:newtok()
        r=urllib.request.Request(B+p,headers={"Authorization":"Bearer "+tok})
        try:return json.load(urllib.request.urlopen(r))
        except urllib.error.HTTPError as e:
            body=e.read().decode()
            if e.code==404:return None
            print(p,e.code,dict(e.headers),body[:200])
            if e.code==401:tok=None;continue
            w=e.headers.get("Retry-After")
            try:w=float(w)
            except:
                try:w=float(json.loads(body).get("retry_after"))
                except:w=2
            time.sleep(w)
        except Exception as e:
            print(p,repr(e));time.sleep(1)
    raise SystemExit("fail "+p)
orders={};dups=0;p=1
while p:
    d=get(f"/orders?page={p}")
    for o in d["items"]:
        if o["id"] in orders:
            dups+=1
            if orders[o["id"]]!=o:print("DIFF",o,orders[o["id"]])
        else:orders[o["id"]]=o
    p=int(d["next"].split("=")[-1]) if d["next"] else None
cust={}
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
tot=0;n=0;reg={"north":0,"south":0,"east":0,"west":0}
for o in orders.values():
    if o["status"]!="shipped":continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None:print("naive",o);t=t.replace(tzinfo=timezone.utc)
    if not lo<=t<hi:continue
    c=o["customer_id"]
    if c not in cust:cust[c]=get("/customers/"+c)
    if cust[c] is None:print("missing cust",o);continue
    a=(o["amount_cents"]*(100-cust[c]["discount_pct"])+50)//100
    tot+=a;n+=1;reg[cust[c]["region"]]+=a
json.dump({"total_cents":tot,"order_count":n,"duplicates_skipped":dups,"by_region":reg},open("/workspace/result.json","w"),indent=2)
print(tot,n,dups,reg,len(orders))
